package com.portafolio.dt.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.UserDetailsService; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserDetailsService users; public JwtFilter(JwtService jwt,UserDetailsService users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,java.io.IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String u=jwt.username(h.substring(7));var d=users.loadUserByUsername(u);SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()));}catch(Exception ignored){}chain.doFilter(req,res);} }
